package com.nextstep.web;
import com.nextstep.entity.*;import com.nextstep.repository.*;import com.nextstep.service.*;
import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import java.time.*;
@RestController @RequestMapping("/api/interviews") public class InterviewController {
 final InterviewQuestionRepository questions;final InterviewSessionRepository sessions;final JsonService json;
 public InterviewController(InterviewQuestionRepository questions,InterviewSessionRepository sessions,JsonService json){this.questions=questions;this.sessions=sessions;this.json=json;}
 record Setup(@NotBlank @Size(max=100) String role,@NotBlank String category,@Min(1) @Max(10) int count,@Min(60) @Max(7200) int durationSeconds){}
 record Answer(@NotBlank @Size(max=20000) String answer,@Min(0) @Max(5) int selfRating){}
 @GetMapping Object history(){return sessions.findByUserIdOrderByCreatedAtDesc(AuthController.uid());}
 @PostMapping Object start(@Valid @RequestBody Setup setup){var bank=new ArrayList<>(questions.findAll().stream().filter(q->setup.category().equals("Mixed")||q.category.equals(setup.category())).filter(q->q.role.equals("All")||q.role.equals(setup.role())).toList());if(bank.isEmpty())throw Errors.bad("No questions for this selection.");Collections.shuffle(bank);var chosen=bank.subList(0,Math.min(setup.count(),bank.size()));var s=new InterviewSession();s.userId=AuthController.uid();s.role=setup.role();s.category=setup.category();s.durationSeconds=setup.durationSeconds();s.elapsedSeconds=0;s.status="IN_PROGRESS";s.questions=json.write(chosen);s.answers="[]";s.score=0;return sessions.save(s);}
 @Transactional @PostMapping("/{id}/answers") Object answer(@PathVariable long id,@Valid @RequestBody Answer a){var s=owned(id);if(!s.status.equals("IN_PROGRESS"))throw Errors.bad("Session is complete.");var answers=(com.fasterxml.jackson.databind.node.ArrayNode)json.read(s.answers);var bank=json.read(s.questions);if(answers.size()>=bank.size())throw Errors.bad("All answers have been saved.");var q=bank.get(answers.size());int words=a.answer().trim().split("\\s+").length;int matched=0;for(String point:q.path("keyPoints").asText().split(","))if(a.answer().toLowerCase(Locale.ROOT).contains(point.trim().toLowerCase(Locale.ROOT)))matched++;int score=Math.min(100,(words>=30?40:words>=15?20:0)+Math.min(60,matched*20));answers.add(json.read(json.write(Map.of("questionId",q.path("id").asLong(),"question",q.path("prompt").asText(),"answer",a.answer(),"selfRating",a.selfRating(),"score",score,"feedback",words<30?"Add a concrete example, your actions and an outcome.":"Review your answer against the model and explain your personal contribution.","modelAnswer",q.path("modelAnswer").asText()))));s.answers=json.write(answers);s.score=(int)java.util.stream.StreamSupport.stream(answers.spliterator(),false).mapToInt(n->n.path("score").asInt()).average().orElse(0);s.elapsedSeconds=(int)Duration.between(s.createdAt,Instant.now()).getSeconds();if(answers.size()==bank.size()||s.elapsedSeconds>=s.durationSeconds)s.status="COMPLETED";return sessions.save(s);}
 @PostMapping("/{id}/finish") Object finish(@PathVariable long id){var s=owned(id);s.status="COMPLETED";s.elapsedSeconds=(int)Duration.between(s.createdAt,Instant.now()).getSeconds();return sessions.save(s);}
 InterviewSession owned(long id){return sessions.findById(id).filter(s->s.userId==AuthController.uid()).orElseThrow(()->Errors.bad("Session not found."));}
}
